  str_n14_1_name_desc = "/",
  str_n14_2_name_desc = "Um ataque repentino de fantasmas na rua. Responda rápido!",
  str_n14_3_name_desc = "O governante de Koufu-jou pode não assumir a responsabilidade por esse tumulto. Quanto mais tempo os poucos de vocês podem durar?",
  str_n14_4_name_desc = "/",
  str_n14_5_name_desc = "Fantasmas estão assombrando todos os cantos de Koufu-jou... Não há onde se esconder.",
  str_n14_6_name_desc = "É hora de deixar de lado velhas partituras. Você tem que unir forças com o Wisp.",
  str_n14_7_name_desc = "A força gasta do Wisp e você podem resistir a esses guerreiros fantasmas?",
  str_n14_8_name_desc = "/",
  str_n14_9_name_desc = "O general está realizando um julgamento público para o Wisp. Seria tarde demais depois da audiência...",
  str_n14_10_name_desc = "A luta entre o general e Nagi é muito intensa para qualquer um de vocês se envolver. Seu campo de batalha está em outro lugar.",
  str_n14_11_name_desc = "Você está a caminho do cemitério, mas há algo além das pétalas das flores de cerejeira caindo como neve...",
  str_n14_12_name_desc = "Quem é o dono do Ameno-habakiri ao lado do túmulo?",
  str_n14_13_name_desc = "/",
  str_n14_14_name_desc = "Uma decisão significativa é tomada nas batidas apressadas do tambor.",
  str_n14_15_name_desc = "Diante de uma crise, Rinne se torna uma nova pessoa...",
  str_n14_16_name_desc = "A chama ardente iluminou o céu... Uma mudança histórica caiu sobre a Ilha das Nuvens esta noite.",
  str_n14_17_name_desc = "/",
  str_n14_1_name_desc_long = "você se encontra com Rinne como planejado, mas Yao está longe de ser visto. A rua está lotada de pessoas ocupadas se preparando para o festival. Amemori aparece brevemente e avisa sobre a aproximação de fantasmas.",
  str_n14_2_name_desc_long = "Fantasmas causam distúrbios na rua. Juntamente com Anzu e Momo, você tenta evacuar os moradores para um local seguro...",
  str_n14_3_name_desc_long = "O general observa o tumulto piorar com indiferença - ele já tem um plano. A cidade é o palco, os civis são o público do espetáculo... E a verdade deve ficar atrás da cortina do palco.\nVocê protege as pessoas enquanto luta contra os fantasmas. Uma força armada de Wisp surge de repente e vira a maré. No entanto, eles parecem hostis.",
  str_n14_4_name_desc_long = "Yao está perdido no castelo principal. O som dos sinos traz de volta uma memória há muito perdida, onde um jovem Yao se escondeu em um guarda-roupa e observou seu mestre matar a sacerdotisa anterior. Desde então, seu mestre foi selado e aprisionado dentro do castelo principal por uma década.",
  str_n14_5_name_desc_long = "O Wisp odeia a sacerdotisa. Considerando vocês como seguidores dela, eles prendem todos vocês antes de contar a história de Cloud Island do ponto de vista do povo aborígene. Eles vêem o general como um invasor implacável. Fantasmas estão se aproximando de você novamente. Você se liberta enquanto o Wisp luta por suas vidas pela segurança dos civis.",
  str_n14_6_name_desc_long = "Cercado por fantasmas, você e o Wisp unem forças para uma pequena chance de sobrevivência. Mas antes que você consiga recuperar o fôlego, o samurai do general aparece à distância, acusando o Wisp de convocar os fantasmas. Essa mentira óbvia finalmente ajuda Rinne decida-se - as sacerdotisas nunca devem enganar. Ela avança para lutar contra o samurai.",
  str_n14_7_name_desc_long = "O ódio de longa data entre o Wisp e a sacerdotisa derrete na frente de um inimigo comum. No entanto, as forças unidas não podem se salvar de uma amarga derrota. O líder Wisp coloca sua última esperança em você, uma sacerdotisa diferente e uma celestita com poderes especiais. O Wisp dá tudo o que tem para cobrir sua fuga.",
  str_n14_8_name_desc_long = "Amemori segue seu mestre. Eles conversam sobre Amemori, o Wisp e seu próprio mestre. Esta é a primeira vez que o adulto Amemori conversa com seu mestre. Ela encontra respostas para muitas de suas perguntas e entende por que seu mestre odeia a sacerdotisa e o general. Eles sobem a torre principal do castelo com garrafas de vinho, onde a obstinada e indisciplinada Espada do Submundo bebe para todos Koufu-jou.",
  str_n14_9_name_desc_long = "Os soldados Wisp são presos e escoltados até o castelo principal pelo samurai para um julgamento aberto. Depois de avaliar a situação, você se comunica telepaticamente com o Wisp e planeja um contra-ataque. Na batalha que se seguiu, a verdadeira natureza do general é revelada quando ele usa o Cloud Mirror para invocar fantasmas diante dos civis. Yao e Amemori venha ajudar. Nagi incendeia o castelo principal antes de pular da torre para lutar contra o general.",
  str_n14_10_name_desc_long = "Dez anos de hostilidade e ressentimento vêm à tona na forma de uma batalha predestinada entre Nagi e o general. Você sai de cena com Amemori para procurar a lendária espada matadora de fantasmas, Slice of Heaven. Sem o conhecimento de ninguém, o general trocou sua humanidade por um poder surpreendente para derrotar Nagi. Esta é uma batalha sem vencedor.",
  str_n14_11_name_desc_long = "Você lutou muito para se livrar do samurai fantasma derramado. E seguindo a memória de Yao, você continua em direção a um cemitério no país, em busca da lendária arma contra fantasmas.",
  str_n14_12_name_desc_long = "O cemitério tranquilo e sereno parece estar bem cuidado. Amemori e Yao discutir sobre a propriedade do Slice of Heaven. Para resolver este assunto, você pega a espada lendária.\nAo lado dele, você descobre um caderno pertencente à sacerdotisa anterior, Tsuki.",
  str_n14_13_name_desc_long = "Você começa a ler a partir da última entrada do caderno. Era uma lembrança de antes e depois de Tsuki se tornar uma sacerdotisa. No diário, ela descreveu a sacerdotisa como a tragédia de Cloud Island. Ela decidiu desistir de resistir pela paz da ilha.\nAlém disso, este caderno é o único lugar onde ela pode guardar suas memórias com Nagi.",
  str_n14_14_name_desc_long = "O conteúdo do caderno sai Amemori e Yao refletindo sobre o fato de que o mundo não é preto e branco. Eles concluem que não podem viver para sempre na sombra de seu mestre.\nEnquanto isso, Rinne e o Wisp teve problemas ao evacuar os cidadãos. Um pedido de socorro ecoa em Koufu-jou na batida de um tambor taiko. Pela primeira vez, Amemori toma uma decisão por conta própria: ela usará o Slice of Heaven para proteger a cidade.",
  str_n14_15_name_desc_long = "Você conhece Rinne no porto enquanto os últimos residentes de Koufu-jou estão embarcando em um navio de refúgio. Com a guerra iminente contra os fantasmas se aproximando, você assiste Rinne enquanto ela faz os arranjos finais e percebe que mudou completamente. Ela carrega o peso de toda a confiança de Koufu-jou em seus ombros.",
  str_n14_16_name_desc_long = "Depois de derrotar inúmeros fantasmas, você vê Fujikumo se aproximar do porto sozinho, agora ele próprio um fantasma. No confronto inevitável, Rinne empunha a Fatia do Céu e a traz sobre o general, que retorna à sua forma humana.\nEnquanto Fujikumo se agarra ao seu último suspiro, uma figura caminha no meio da multidão e para ao seu lado.",
  str_n14_17_name_desc_long = "Nagi levanta sua lâmina e liberta Fujikumo da humilhação. As antigas pontuações entre o trio de Nagi, Fujikumo e Tsuki finalmente chegam ao fim. Quando o sol nascer novamente, os vivos continuarão com uma nova vida.\nO Koufu-jou devastado pela guerra consegue se recompor após a calamidade. Uma nova Ilha das Nuvens nasce. No porto, as despedidas são feitas entre amigos.",
  str_n14_minigame_stage_title1 = "Batalha do Peixinho Dourado",
  str_n14_minigame_stage_title2 = "Presente do Comandante da Legião",
  str_n14_minigame_stage_title3 = "Passado de Koufu-jou",
  str_n14_minigame_stage_title4 = "Um visitante de longe",
  str_n14_minigame_stage_title5 = "Traje Antigo",
  str_n14_minigame_stage_title6 = "É ele!",
  str_n14_minigame_stage_desc1 = "O grupo assume uma missão misteriosa, mas antes que os arranjos possam ser feitos, Yao e Amemori envolver-se inesperadamente em uma competição de pesca! Bem, o que está feito está feito... Agora a pergunta é, quem vai pegar mais peixes?",
  str_n14_minigame_stage_desc2 = "O que?! O Comandante da Legião realmente patrocinou esta barraca... Opa, eu e minha boca grande. Eu não queria estragar o disfarce dela.",
  str_n14_minigame_stage_desc3 = "O garotinho que te deu os grãos de soja levou o pai para a barraca... Ele era todo sorrisos e parecia muito feliz.",
  str_n14_minigame_stage_desc4 = "Um visitante de longe fez Amemori desconfortável... Quem é? O que traz o visitante à banca?",
  str_n14_minigame_stage_desc5 = "A atmosfera na barraca é tensa quando ele se aproxima. Amemori e Yao estão prontos para proteger Rinne! Mas Rinne está em silêncio... Qual é a história por trás disso?",
  str_n14_minigame_stage_desc6 = "O verdadeiro dono da barraca voltou... e é ele? Céus, todos nós devemos aprender o segredo de seu negócio...",
